def finish(item, deadline, monitor=False):
    (p, o, e) = item
    while p.poll() is None:
        assert time.monotonic() < deadline
        healthy()
        if monitor:
            sample(deadline)
        time.sleep(0.5)
    assert time.monotonic() < deadline
    if p.returncode != 0:
        raise subprocess.CalledProcessError(p.returncode, p.args)
    assert o.stat().st_size <= 64 << 20 and e.stat().st_size <= 64 << 20
    return o.read_text()

def health_wait():
    limit = time.monotonic() + 120
    while True:
        try:
            assert HTTP('/health', None, 5)['status'] == 200
            break
        except subprocess.CalledProcessError:
            assert services['api'][0].poll() is None, 'API startup process exited'
            assert time.monotonic() < limit
            healthy()
            time.sleep(0.5)
